    taxonomy: tax("Chordata", "脊索动物门", "Mammalia", "哺乳纲", "Chiroptera", "翼手目", "Noctilionidae", "兔唇蝠科", "Noctilio", "兔唇蝠属"),
    general: ["Animal Diversity Web, University of Michigan Museum of Zoology", "https://animaldiversity.org/accounts/Noctilio_leporinus/"],
    range: ["Animal Diversity Web range account", "https://animaldiversity.org/accounts/Noctilio_leporinus/"],
    summary: b("The Greater Bulldog Bat is a large fishing bat of tropical American rivers, lakes, estuaries and coasts. It uses echolocation to detect tiny disturbances at the water surface, then rakes the water with oversized feet and curved claws.", "大兔唇蝠是热带美洲河流、湖泊、河口和海岸的大型食鱼蝙蝠。它用回声定位探测水面微小扰动，再以巨大的脚和弯爪掠过水面抓取猎物。"),
    anatomy: b("Head-body length is about 10–13 cm; males average heavier than females and may reach roughly 75–80 g. The species has long hind legs, enormous feet, strongly curved claws and cheek pouches for carrying prey.", "头体长约10–13厘米；雄性平均比雌性重，可达约75–80克。它具有长后腿、巨足、强弯爪和用于携带猎物的颊囊。"),
    ecology: b("It roosts in hollow trees, caves or buildings near water. At night it flies low over calm surfaces, eating fish and aquatic insects; it may also hunt over the sea and carry captured prey to a perch.", "它栖息在水边的树洞、洞穴或建筑中。夜间贴近平静水面飞行，取食鱼和水生昆虫；也可能在海面捕猎，并把猎物带到栖处。"),
    rangeText: b("Occurs from western and southern Mexico through Central America and much of tropical South America to northern Argentina and southeastern Brazil, as well as many Caribbean islands. Suitable areas combine open water with nearby daytime roosts.", "从墨西哥西部和南部经中美洲，广布至南美热带地区、阿根廷北部和巴西东南部，也见于许多加勒比岛屿。适宜地点需同时具有开阔水面和附近的日间栖息处。"),
    facts: [
      fact("body_length", "Head-body length", "头体长", "About 10–13 cm", "约10–13厘米"),
      fact("mass", "Adult mass", "成体体重", "About 60–80 g; males are usually heavier", "约60–80克；雄性通常更重"),
      fact("main_prey", "Main prey", "主要猎物", "Fish and aquatic insects", "鱼类和水生昆虫", ["ecology"]),
      fact("hunting", "Hunting method", "捕猎方式", "Echolocation plus feet raked across the surface", "回声定位并以双足掠过水面", ["ecology"]),
    ],
    life: b("Breeding is seasonal and varies regionally. Females generally bear one young; maternity groups shelter in warm roosts, and the juvenile is nursed until it can fly and capture its own prey.", "繁殖具有季节性且因地区而异。雌性通常产一仔；育幼群栖息在温暖隐蔽处，幼仔吃奶直至能够飞行并自行捕猎。"),
    adaptations: [
      adaptation("Oversized fishing feet", "巨型捕鱼足", "Long toes and hook-like claws sweep just below the surface and close around prey.", "长趾和钩状爪在水面下方掠过并扣住猎物。"),
      adaptation("Surface-reading sonar", "读取水面的声呐", "Echolocation can detect ripples made by prey close to the surface.", "回声定位可探测猎物在水面附近造成的涟漪。"),
      adaptation("Cheek pouches", "颊囊", "Expandable cheek pouches help hold fish while the bat remains in flight.", "可扩张颊囊有助在飞行中暂存鱼类。"),
    ],
    role: b("It connects aquatic and terrestrial food webs by removing fish and insects from the water and depositing remains and guano at roosts. It is also prey for owls, snakes and other nocturnal predators.", "它从水中捕食鱼和昆虫，并在栖息地留下残骸与粪便，从而连接水生和陆生食物网；它也会成为猫头鹰、蛇及其他夜行捕食者的猎物。"),
    threats: b("Globally Least Concern, but local colonies can be lost through roost destruction, wetland degradation, water pollution and deliberate bat control.", "全球为无危，但局部群体可能因栖息地毁坏、湿地退化、水污染和人为灭蝠而消失。"),
    actions: b("Protect hollow trees and cave roosts near clean waterways, reduce pesticide and contaminant inputs, and retain calm shoreline foraging zones.", "应保护清洁水域附近的树洞与洞穴栖息地，减少农药和污染物输入，并保留平静的岸边觅食区。"),
    identify: b("A large reddish or gray-brown bat with a wrinkled, bulldog-like muzzle, narrow pointed wings, very long legs and conspicuously oversized feet.", "大型、红褐或灰褐色蝙蝠，吻部皱褶似斗牛犬，翼狭尖，后腿很长，脚异常巨大醒目。"),
    similar: b("The Lesser Bulldog Bat is smaller, has proportionally smaller feet and relies more heavily on insects. Exact photographs should show the large feet and robust body, not merely a bat over water.", "小兔唇蝠体型更小，脚相对较小，更偏食昆虫。可靠照片应能看到巨足和粗壮体型，不能只凭“水面上的蝙蝠”判断。"),
    senses: b("Rapid ultrasonic calls guide flight and locate surface prey. Smell and social calls are important within crowded roosts, while tactile feedback from feet helps secure a catch.", "快速超声叫声用于导航和定位水面猎物。嗅觉和社会叫声在拥挤栖息地中很重要，足部触觉反馈则帮助抓稳猎物。"),
    seasonal: b("Foraging follows local fish, insect and rainfall cycles. Reproductive timing differs among regions, so a single month range should not be applied across its entire tropical distribution.", "觅食随当地鱼类、昆虫和降雨周期变化。各地繁殖时间不同，不能把单一月份范围套用于整个热带分布区。"),
    humans: b("Its fishing behavior fascinates observers, but colonies in roofs or structures may create conflict. Exclusion should occur only outside maternity periods and preserve alternative roosts.", "其捕鱼行为很受关注，但在屋顶或建筑中栖息可能引发冲突。封堵应避开育幼期，并保留替代栖息地。"),
    field: b("At dusk, look for a large bat flying repeated low passes over open water and briefly dragging both feet across the surface. Roost droppings may contain fish scales or insect remains.", "黄昏时可寻找在开阔水面反复低飞、短暂用双足划过水面的较大蝙蝠；栖息地粪便中可能含鱼鳞或昆虫残片。"),
    trivia: [
      trivia("It can detect a fish's wake with echolocation even when the fish is just below the surface.", "即使鱼只在水面下方游动，它也能用回声定位探测其尾流。"),
      trivia("The hind feet are proportionally among the largest of any bat.", "它的后足相对体型而言在蝙蝠中名列前茅。"),
      trivia("Most food is caught by the bat itself; fishing is not limited to scavenging dead fish.", "其食物大多由自己捕获，捕鱼并非只捡食死鱼。"),
    ],
    classModule: classSection("A mammal that fishes in flight", "飞行捕鱼的哺乳动物", "The bat remains airborne while its feet trace the surface. Once the claws hook prey, the tail membrane and cheek pouches help control the catch before it is eaten.", "蝙蝠保持飞行，让双足划过水面。爪钩住猎物后，尾膜和颊囊帮助控制猎物，再将其吃掉。"),
    map: [5, -73], zoom: 2,
    polygons: [[[31, -116], [27, -97], [18, -85], [24, -81], [20, -74], [10, -61], [4, -51], [-5, -35], [-24, -42], [-35, -58], [-25, -68], [-8, -78], [8, -82], [18, -105], [31, -116]]],
