function buildSources(p) {
  const taxonomyPair = p.taxonomySource || ["GBIF Backbone Taxonomy API", `https://api.gbif.org/v1/species/${p.gbif}`];
  const ecologyPair = p.ecologySource || p.general;
  return {
    taxonomy: source(...taxonomyPair),
    conservation: source("IUCN Red List category linked through the GBIF Species API", `https://api.gbif.org/v1/species/${p.gbif}/iucnRedListCategory`),
    general: source(...p.general),
    ecology: source(...ecologyPair),
    range: source(...p.range),
  };
}

function buildRecord(p) {
  const [statusEn, statusZh] = statusLabels[p.status];
  const hasPolygons = p.polygons.length > 0;
  const defaultStatusNote = p.status === "NE"
    ? b("No species-level global IUCN assessment was confirmed. Not Evaluated means assessment is absent, not that the species is secure or abundant.", "未确认到物种级IUCN全球评估。未评估表示缺少评估，并不表示该物种安全或数量丰富。")
    : b(`The current species-level global category checked on ${CHECKED} is ${statusEn}; regional and legal categories may differ.`, `已于${CHECKED}核对当前物种级全球等级为${statusZh}；地区等级和法律地位可能不同。`);
  const statusNote = p.statusNote || defaultStatusNote;
  return {
    content_version: 2,
    content_review: REVIEWED ? {
      factual_qc: "source-checked",
      bilingual_qc: "line-by-line-reviewed",
      reviewed_at: CHECKED,
      reviewer: "Codex exact-taxon source, bilingual and range audit",
      notes: "Every English and Chinese section was compared line by line; exact-taxon identity, conservation mapping, numeric claims, visual identification risks and generalized range geometry were checked against the cited sources. Polygon boundaries are display generalizations and never imply continuous occupancy.",
    } : { factual_qc: "pending", bilingual_qc: "pending" },
    id: p.id,
    name_zh: p.nameZh,
    name_en: p.nameEn,
    scientific_name: p.scientific,
    ui_tags: p.tags,
    taxonomy: p.taxonomy,
    conservation_status: {
      code: p.status,
      en: statusEn,
      zh: statusZh,
      note_en: statusNote.en,
      note_zh: statusNote.zh,
    },
    description: p.summary,
    encyclopedia: {
      anatomy: sourced(p.anatomy.en, p.anatomy.zh, ["general"]),
      ecology_and_behavior: sourced(p.ecology.en, p.ecology.zh, ["general", "ecology"]),
      habitat_and_distribution: sourced(p.rangeText.en, p.rangeText.zh, ["range"]),
    },
    rich_content: {
      quick_facts: p.facts,
      life_cycle_and_reproduction: sourced(p.life.en, p.life.zh, ["general", "ecology"]),
      adaptations: p.adaptations,
      ecological_role: sourced(p.role.en, p.role.zh, ["ecology"]),
      conservation_and_threats: {
        population_trend: p.trend,
        threats: p.threats,
        actions: p.actions,
        source_keys: ["conservation", "general"],
      },
      identification: {
        key_features: p.identify,
        similar_species: p.similar,
        source_keys: ["general", "taxonomy"],
      },
      communication_and_senses: sourced(p.senses.en, p.senses.zh, ["general", "ecology"]),
      seasonal_calendar: sourced(p.seasonal.en, p.seasonal.zh, ["general", "ecology"]),
      relationship_with_humans: sourced(p.humans.en, p.humans.zh, ["general", "conservation"]),
      evolution: sourced(
        `${p.nameEn} is placed in genus ${p.taxonomy.genus.en}, family ${p.taxonomy.family.en}, order ${p.taxonomy.order.en}. This record follows the accepted binomial ${p.scientific} and does not transfer claims or images from look-alike species.`,
        `${p.nameZh}归入${p.taxonomy.genus.zh}、${p.taxonomy.family.zh}、${p.taxonomy.order.zh}。本条目采用接受学名${p.scientific}，不从外形相近物种移用说法或图片。`,
        ["taxonomy"],
      ),
      field_signs: sourced(p.field.en, p.field.zh, ["general", "ecology"]),
      did_you_know: p.trivia,
      class_specific: [p.classModule],
    },
    habitat: {
      text_en: p.rangeText.en,
      text_zh: p.rangeText.zh,
      map_coordinates: p.map,
      map_zoom_level: p.zoom,
      global_distribution_polygons: p.polygons,
      range_review: {
        display_mode: hasPolygons ? "verified-polygon" : "representative-point",
        previous_result: "not-applicable",
        source_keys: ["range"],
        comparison_en: hasPolygons
          ? "This new record has no previous geometry. The displayed nonrectangular polygons are a conservative, simplified tracing of the cited institutional range account for readable world-map display; boundaries are generalized and do not imply continuous occupancy within every enclosed area."
          : "This new record has no previous geometry. The authoritative range account describes widely scattered oceanic or island occurrences for which one filled polygon would falsely imply continuous habitat, so the map uses a clearly labelled representative point rather than a guessed boundary.",
        comparison_zh: hasPolygons
          ? "这是没有旧几何的新记录。显示的非矩形多边形依据所引机构分布资料保守概化，以便世界地图清晰呈现；边界为概括范围，不表示圈内每处都有连续分布。"
          : "这是没有旧几何的新记录。权威分布资料描述跨广阔海域或离散岛屿的记录，单一填色多边形会错误暗示连续生境；因此地图使用明确标注的代表点，而不猜测边界。",
        checked_at: CHECKED,
      },
    },
    image: null,
    sources: buildSources(p),
  };
}

const records = profiles.map(buildRecord);
if (records.length !== 25) throw new Error(`Expected 25 profiles, found ${records.length}`);
fs.writeFileSync(OUT, `${JSON.stringify(records, null, 2)}\n`);
process.stdout.write(`Wrote ${records.length} ${REVIEWED ? "reviewed" : "pending"} records to ${OUT}\n`);
